{"path":"verify.py","content":"import hashlib
import os


def verify_file(path, expected_sha256: str) -> bool:
    """Stream-hash the file at `path` with SHA-256 and return whether
    the hex digest equals `expected_sha256`.  Returns False if the
    file does not exist (no exception is raised)."""
    if not os.path.exists(path):
        return False

    sha256 = hashlib.sha256()
    try:
        with open(path, "rb") as f:
            while True:
                chunk = f.read(8192)
                if not chunk:
                    break
                sha256.update(chunk)
    except (OSError, IOError):
        return False

    return sha256.hexdigest() == expected_sha256
